//! The maze world: three fixed layouts, generated by a recursive backtracker from fixed seeds.

/// A maze as a grid of `2n + 1` by `2n + 1` flags: `true` is wall. Cell `(i, j)` is at grid
/// `(2i + 1, 2j + 1)`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MazeGrid {
    /// Cells per side.
    pub n: usize,
    /// `walls[y][x]`.
    pub walls: Vec<Vec<bool>>,
}

struct XorShift(u64);

impl XorShift {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
}

/// The layout for `seed`: a perfect maze (every cell reachable, exactly one path between two cells).
pub fn generate(n: usize, seed: u64) -> MazeGrid {
    let m = 2 * n + 1;
    let mut walls = vec![vec![true; m]; m];
    let mut rng = XorShift(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1);
    let mut visited = vec![vec![false; n]; n];
    let mut stack = vec![(0usize, 0usize)];
    visited[0][0] = true;
    walls[1][1] = false;
    while let Some(&(i, j)) = stack.last() {
        let mut next = Vec::new();
        if i + 1 < n && !visited[j][i + 1] {
            next.push((i + 1, j));
        }
        if j + 1 < n && !visited[j + 1][i] {
            next.push((i, j + 1));
        }
        if i > 0 && !visited[j][i - 1] {
            next.push((i - 1, j));
        }
        if j > 0 && !visited[j - 1][i] {
            next.push((i, j - 1));
        }
        if next.is_empty() {
            stack.pop();
            continue;
        }
        let (ni, nj) = next[(rng.next() % next.len() as u64) as usize];
        // Open the wall between the two cells, then the new cell.
        walls[j + nj + 1][i + ni + 1] = false;
        walls[2 * nj + 1][2 * ni + 1] = false;
        visited[nj][ni] = true;
        stack.push((ni, nj));
    }
    MazeGrid { n, walls }
}

impl MazeGrid {
    /// Whether you can go from cell `(i, j)` to the next cell in direction `(di, dj)`.
    pub fn open(&self, i: usize, j: usize, di: i32, dj: i32) -> bool {
        let x = (2 * i + 1) as i32 + di;
        let y = (2 * j + 1) as i32 + dj;
        !self.walls[y as usize][x as usize]
    }

    /// Length of the shortest path (in cells moved) from the start cell `(0, 0)` to the goal cell
    /// `(n - 1, n - 1)`, or `None` when there is none.
    pub fn shortest_path(&self) -> Option<usize> {
        let n = self.n;
        let mut dist = vec![vec![usize::MAX; n]; n];
        dist[0][0] = 0;
        let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
        while let Some((i, j)) = queue.pop_front() {
            for (di, dj) in [(1, 0), (0, 1), (-1, 0), (0, -1)] {
                let (ni, nj) = (i as i32 + di, j as i32 + dj);
                if ni < 0 || nj < 0 || ni >= n as i32 || nj >= n as i32 {
                    continue;
                }
                let (ni, nj) = (ni as usize, nj as usize);
                if self.open(i, j, di, dj) && dist[nj][ni] == usize::MAX {
                    dist[nj][ni] = dist[j][i] + 1;
                    queue.push_back((ni, nj));
                }
            }
        }
        let d = dist[n - 1][n - 1];
        (d != usize::MAX).then_some(d)
    }

    /// Wall segments `(from, to)` in metres for cells of `cell_m`, runs merged. Corner posts are
    /// included in the runs.
    pub fn segments(&self, cell_m: f64) -> Vec<([f64; 2], [f64; 2])> {
        let m = 2 * self.n + 1;
        let half = cell_m / 2.0;
        let mut out = Vec::new();
        // Horizontal runs on even rows.
        for y in (0..m).step_by(2) {
            let mut x = 0;
            while x < m {
                if self.walls[y][x] && x + 1 < m && self.walls[y][x + 1] {
                    let x0 = x;
                    while x + 1 < m && self.walls[y][x + 1] {
                        x += 1;
                    }
                    out.push((
                        [x0 as f64 * half, y as f64 * half],
                        [x as f64 * half, y as f64 * half],
                    ));
                }
                x += 1;
            }
        }
        // Vertical runs on even columns.
        for x in (0..m).step_by(2) {
            let mut y = 0;
            while y < m {
                if self.walls[y][x] && y + 1 < m && self.walls[y + 1][x] {
                    let y0 = y;
                    while y + 1 < m && self.walls[y + 1][x] {
                        y += 1;
                    }
                    out.push((
                        [x as f64 * half, y0 as f64 * half],
                        [x as f64 * half, y as f64 * half],
                    ));
                }
                y += 1;
            }
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn layouts_are_perfect_mazes_and_solvable() {
        for seed in [11, 22, 33, 1, 2, 3] {
            let g = generate(6, seed);
            // Perfect: n*n - 1 openings between cells.
            let mut openings = 0;
            for j in 0..6 {
                for i in 0..6 {
                    if i + 1 < 6 && g.open(i, j, 1, 0) {
                        openings += 1;
                    }
                    if j + 1 < 6 && g.open(i, j, 0, 1) {
                        openings += 1;
                    }
                }
            }
            assert_eq!(openings, 35, "seed {seed}");
            assert!(g.shortest_path().is_some(), "seed {seed}");
        }
    }

    #[test]
    fn the_same_seed_gives_the_same_layout_and_seeds_differ() {
        assert_eq!(generate(6, 11), generate(6, 11));
        assert_ne!(generate(6, 11), generate(6, 22));
        assert_ne!(generate(6, 22), generate(6, 33));
    }

    #[test]
    fn the_outer_wall_is_closed() {
        let g = generate(6, 11);
        let segs = g.segments(0.25);
        assert!(segs.contains(&([0.0, 0.0], [1.5, 0.0])));
        assert!(segs.contains(&([0.0, 1.5], [1.5, 1.5])));
    }
}
